<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Policy\Allow;

use Throwable;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Update\UserPersonalApiKeyUpdateAllowDecision;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Retrieve\UserPersonalApiKeyRetrieveAllowDecision;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Delete\UserPersonalApiKeyDeleteAllowDecision;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Revoke\UserPersonalApiKeyRevokeAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Security\AllowDecision;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class IsSelfUserAllow
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function checkUpdate(UserPersonalApiKeyUpdateAllowDecision $proposal): AllowDecision
    {
        return $this->check('UserPersonalApiKeyUpdateAllowDecision', $proposal);
    }
    public function checkRetrieve(UserPersonalApiKeyRetrieveAllowDecision $proposal): AllowDecision
    {
        return $this->check('UserPersonalApiKeyRetrieveAllowDecision', $proposal);
    }
    public function checkDelete(UserPersonalApiKeyDeleteAllowDecision $proposal): AllowDecision
    {
        return $this->check('UserPersonalApiKeyDeleteAllowDecision', $proposal);
    }
    public function checkRevoke(UserPersonalApiKeyRevokeAllowDecision $proposal): AllowDecision
    {
        return $this->check('UserPersonalApiKeyRevokeAllowDecision', $proposal);
    }
    private function check(string $name, AllowDecision $proposal): AllowDecision
    {
        $this->logDebug("Check " . $name . " on IsSelfUserAllow User personal api key");
        $span = $this->startSpan("Check " . $name . " on IsSelfUserAllow User personal api key");
        try {
            $identity = $this->context->getIdentity();
            if ($proposal->isAllowed()) {
                if (!$proposal->getUser()->getUid() == $identity->getUid()) {
                    $proposal->deny('Disabled if not IsSelfUser');
                }
            }
            return $proposal;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
